"use client";

import { FormEvent, useEffect, useState } from "react";
import Link from "next/link";
import {
  LearningCourse,
  loadLearningCourses,
  saveLearningCourses,
} from "../../lib/storage";

export default function CoursesPage() {
  const [courses, setCourses] = useState<LearningCourse[]>([]);
  const [name, setName] = useState("");
  const [durationHours, setDurationHours] = useState(4);
  const [skill, setSkill] = useState("Beginner");
  const [isCreating, setIsCreating] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => setCourses(loadLearningCourses()), []);

  async function createCourse(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setIsCreating(true);
    setError("");
    try {
      const response = await fetch("/api/generate-course", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, durationHours, skill }),
      });
      const result = await response.json();
      if (!response.ok)
        throw new Error(result.error || "Unable to create course");
      const nextCourses = [result as LearningCourse, ...courses];
      saveLearningCourses(nextCourses);
      setCourses(nextCourses);
      setName("");
    } catch (creationError) {
      setError(
        creationError instanceof Error
          ? creationError.message
          : "Unable to create course",
      );
    } finally {
      setIsCreating(false);
    }
  }

  function deleteCourse(id: string) {
    const nextCourses = courses.filter((course) => course.id !== id);
    saveLearningCourses(nextCourses);
    localStorage.removeItem(`am_course_progress_${id}`);
    setCourses(nextCourses);
  }

  return (
    <div className="min-h-screen bg-[#f3efe8] text-[#172323]">
      <header className="mx-auto flex h-20 max-w-[1440px] items-center justify-between border-b border-[#172323]/15 px-5 sm:h-24 sm:px-8 lg:px-14">
        <Link
          className="group flex items-center gap-3 text-[18px] font-bold tracking-[-0.04em]"
          href="/"
        >
          <span className="grid size-9 place-items-center bg-[#ed674f] font-mono text-[11px] tracking-[-0.12em] text-[#f3efe8] transition-transform duration-300 group-hover:-rotate-6">
            AM
          </span>
          <span>Ask Me</span>
        </Link>
        <nav className="flex items-center gap-3 sm:gap-8">
          <span className="hidden font-mono text-[10px] uppercase tracking-[0.12em] text-[#65716d] sm:inline">
            Learning studio
          </span>
          <Link
            className="border border-[#172323] px-3 py-2 text-[11px] font-bold transition-colors hover:bg-[#172323] hover:text-[#f3efe8] sm:px-4 sm:py-2.5 sm:text-[12px]"
            href="/interviews"
          >
            Mock interviews{" "}
            <span className="ml-2 text-base" aria-hidden="true">
              ↗
            </span>
          </Link>
        </nav>
      </header>
      <main className="mx-auto max-w-[1440px] px-5 sm:px-8 lg:px-14">
        <section className="grid gap-10 border-b border-[#172323]/15 py-14 sm:py-20 lg:grid-cols-[minmax(0,1fr)_320px] lg:items-end lg:gap-20">
          <div>
            <p className="mb-6 font-mono text-[10px] uppercase tracking-[0.13em] text-[#65716d]">
              <span className="mr-2 inline-block size-2 rounded-full bg-[#ed674f]" />{" "}
              Build your syllabus
            </p>
            <h1 className="font-display text-[clamp(4rem,10vw,9rem)] font-medium leading-[0.86] tracking-[-0.065em]">
              Learn with
              <br />
              <em className="text-[#ed674f]">intention.</em>
            </h1>
          </div>
          <p className="max-w-sm text-sm leading-7 text-[#65716d] lg:mb-2">
            Give Gemini a goal, a timeframe, and your experience level. It will
            shape a focused course you can work through one hour at a time.
          </p>
        </section>
        <section className="grid gap-10 border-b border-[#172323]/15 py-12 sm:py-16 lg:grid-cols-[150px_minmax(0,620px)_1fr] lg:gap-10">
          <div className="font-mono text-[10px] uppercase tracking-[0.12em] text-[#ed674f]">
            <span>01</span>
            <p className="my-3 text-[#172323]">Create a course</p>
            <span className="block h-px w-14 bg-[#ed674f]" />
          </div>
          <form
            className="relative overflow-hidden bg-[#e6dfd2] p-6 shadow-[10px_10px_0_#8db7ad] sm:p-10"
            onSubmit={createCourse}
          >
            <div className="absolute right-0 top-0 h-28 w-28 translate-x-10 -translate-y-10 rounded-full border-[18px] border-[#ed674f]/20" />
            <div className="relative">
              <p className="font-mono text-[10px] uppercase tracking-[0.12em] text-[#ed674f]">
                AI curriculum designer
              </p>
              <h2 className="mt-3 font-display text-4xl font-medium leading-[0.92] tracking-[-0.055em] sm:text-5xl">
                What do you want
                <br />
                <em className="text-[#ed674f]">to master?</em>
              </h2>
            </div>
            <div className="relative mt-9 grid gap-6">
              <div>
                <label
                  className="mb-2 block font-mono text-[10px] uppercase tracking-[0.1em] text-[#65716d]"
                  htmlFor="course-name"
                >
                  Course name
                </label>
                <input
                  className="w-full border-0 border-b border-[#172323]/30 bg-transparent px-0 py-3 text-sm outline-none placeholder:text-[#65716d]/60 focus:border-[#ed674f]"
                  id="course-name"
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  placeholder="e.g. Product design fundamentals"
                  required
                />
              </div>
              <div className="grid grid-cols-[1fr_110px] gap-4">
                <div>
                  <label
                    className="mb-2 block font-mono text-[10px] uppercase tracking-[0.1em] text-[#65716d]"
                    htmlFor="course-skill"
                  >
                    Experience
                  </label>
                  <select
                    className="w-full border-0 border-b border-[#172323]/30 bg-transparent px-0 py-3 text-sm outline-none focus:border-[#ed674f]"
                    id="course-skill"
                    value={skill}
                    onChange={(event) => setSkill(event.target.value)}
                  >
                    <option>Beginner</option>
                    <option>Experienced</option>
                  </select>
                </div>
                <div>
                  <label
                    className="mb-2 block font-mono text-[10px] uppercase tracking-[0.1em] text-[#65716d]"
                    htmlFor="course-duration"
                  >
                    Hours
                  </label>
                  <input
                    className="w-full border-0 border-b border-[#172323]/30 bg-transparent px-0 py-3 text-sm outline-none focus:border-[#ed674f]"
                    id="course-duration"
                    type="number"
                    min="1"
                    max="24"
                    value={durationHours}
                    onChange={(event) =>
                      setDurationHours(Number(event.target.value))
                    }
                    required
                  />
                </div>
              </div>
              {error && (
                <p
                  className="border-l-2 border-[#ed674f] bg-[#ed674f]/10 px-3 py-2 text-sm text-[#8c3829]"
                  role="alert"
                >
                  {error}
                </p>
              )}
              <button
                className="flex w-full items-center justify-between bg-[#172323] px-5 py-4 text-left text-sm font-bold text-[#f3efe8] transition-transform hover:-translate-y-0.5 disabled:cursor-wait disabled:opacity-60"
                disabled={isCreating}
              >
                {isCreating ? "Designing your course..." : "Generate course"}
                <strong className="text-xl font-normal">
                  {isCreating ? "..." : "↗"}
                </strong>
              </button>
            </div>
          </form>
          <div className="flex max-w-xs items-start gap-4 self-end text-sm leading-6 text-[#65716d] lg:pb-2">
            <span className="text-2xl text-[#ed674f]">✦</span>
            <p>
              Every hour becomes one lecture. Every lecture becomes four clear
              moments to understand, question, and practice.
            </p>
          </div>
        </section>
        <section className="py-16 sm:py-24">
          <div className="mb-10 flex items-end justify-between gap-6 sm:mb-14">
            <div>
              <p className="mb-5 font-mono text-[10px] uppercase tracking-[0.13em] text-[#65716d]">
                Your curriculum
              </p>
              <h2 className="font-display text-5xl font-medium leading-[0.9] tracking-[-0.06em] sm:text-7xl">
                Keep going,
                <br />
                <em className="text-[#ed674f]">one hour at a time.</em>
              </h2>
            </div>
            <div className="flex items-end gap-3">
              <strong className="font-display text-5xl font-medium leading-none text-[#ed674f] sm:text-7xl">
                {String(courses.length).padStart(2, "0")}
              </strong>
              <span className="mb-1 font-mono text-[10px] uppercase leading-4 tracking-[0.1em] text-[#65716d]">
                courses
                <br />
                created
              </span>
            </div>
          </div>
          {courses.length === 0 ? (
            <div className="flex items-center gap-5 border-y border-[#172323]/15 py-10 text-[#65716d]">
              <span className="text-3xl text-[#ed674f]">✦</span>
              <div>
                <h3 className="font-display text-3xl text-[#172323]">
                  Your curriculum is waiting.
                </h3>
                <p className="mt-2 text-sm">
                  Create a course above and your learning path will live here.
                </p>
              </div>
            </div>
          ) : (
            <div className="grid gap-4">
              {courses.map((course, index) => (
                <article
                  className="group border border-[#172323]/15 bg-[#f7f4ee] p-5 transition-all duration-300 hover:-translate-y-1 hover:border-[#ed674f] hover:shadow-[8px_8px_0_#8db7ad] sm:p-7"
                  key={course.id}
                >
                  <div className="flex items-center justify-between border-b border-[#172323]/10 pb-5 font-mono text-[10px] uppercase tracking-[0.1em] text-[#65716d]">
                    <span className="text-[#ed674f]">
                      {String(index + 1).padStart(2, "0")}
                    </span>
                    <span>
                      <i className="mr-2 inline-block size-2 rounded-full bg-[#8db7ad]" />{" "}
                      {course.durationHours} hour path
                    </span>
                  </div>
                  <div className="flex items-start justify-between gap-6 py-7">
                    <div>
                      <h3 className="font-display text-3xl font-medium tracking-[-0.045em] sm:text-4xl">
                        {course.name}
                      </h3>
                      <div className="mt-4 flex flex-wrap gap-x-5 gap-y-2 font-mono text-[10px] uppercase tracking-[0.08em] text-[#65716d]">
                        <span>{course.skill}</span>
                        <span>{course.lectures.length} lectures</span>
                        <span>Gemini designed</span>
                      </div>
                    </div>
                    <span
                      className="text-3xl text-[#ed674f] transition-transform duration-300 group-hover:translate-x-1 group-hover:-translate-y-1"
                      aria-hidden="true"
                    >
                      ↗
                    </span>
                  </div>
                  <div className="flex items-center justify-between border-t border-[#172323]/10 pt-5">
                    <Link
                      className="text-sm font-bold hover:text-[#ed674f]"
                      href={`/courses/${course.id}`}
                    >
                      Open course <span className="ml-3">→</span>
                    </Link>
                    <button
                      className="text-xs text-[#65716d] underline decoration-[#65716d]/40 underline-offset-4 hover:text-[#ed674f]"
                      onClick={() => deleteCourse(course.id)}
                    >
                      Delete course
                    </button>
                  </div>
                </article>
              ))}
            </div>
          )}
        </section>
      </main>
      <footer className="mx-auto flex max-w-[1440px] flex-col gap-3 border-t border-[#172323]/15 px-5 py-8 font-mono text-[10px] uppercase tracking-[0.08em] text-[#65716d] sm:flex-row sm:items-center sm:justify-between sm:px-8 lg:px-14">
        <div>
          <span className="font-sans text-base font-bold normal-case tracking-[-0.03em] text-[#172323]">
            Ask Me
          </span>
          <span className="ml-3 normal-case tracking-normal">
            A better conversation with your future.
          </span>
        </div>
        <div className="flex items-center gap-6">
          <span>© 2026</span>
          <Link className="text-[#172323] hover:text-[#ed674f]" href="/">
            Home ↗
          </Link>
        </div>
      </footer>
    </div>
  );
}
